node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// 1. Turn off cellular service for device_0
db.prepare('UPDATE ts_device_settings SET cellular = 0 WHERE device_id = ?').run('device_0');
const settings = db.prepare('SELECT * FROM ts_device_settings WHERE device_id = ?').get('device_0');
console.log('=== Cellular Status After Update ===');
console.log(JSON.stringify(settings, null, 2));

// 2. Search for the four contacts
const names = ['Maya Bennett', 'Jordan Kim', 'Sofia Ramirez', 'Elena Ramirez'];
console.log('\n=== Contact Lookup ===');
const allContacts = db.prepare('SELECT * FROM ts_contacts').all();
console.log('All contacts in DB (' + allContacts.length + '):');
console.log(JSON.stringify(allContacts, null, 2));

console.log('\n=== Matching Contacts ===');
for (const name of names) {
  const matches = allContacts.filter(c => c.name.toLowerCase().includes(name.toLowerCase()) || name.toLowerCase().includes(c.name.toLowerCase()));
  if (matches.length > 0) {
    matches.forEach(m => console.log(JSON.stringify(m)));
  } else {
    console.log('No match for: ' + name);
  }
}
"
